%[text] # MEMS arch example
%[text] Worked example of the MEMS arch found in [Evaluating applied force reduced-order models: validation](https://doi.org/10.1007/s11071-026-12844-7)
%[text] ![](text:image:397c)
%[text] Make sure '`AFR_tool.prj`' is open
%%
%[text] The logging and visualisation levels determine how much is outputted to the console and as graphical representations respectively. The higher the number, the more verbose the output.
clear
set_script_wd(); %sets working directory to "...\mems_arch"
set_logging_level(3)
set_visualisation_level(3)
%%
%[text] The model can be re-meshed with a specified seed size
seed_size = 0.00307;
% 0.00307 ->   105,765 DoFs
% 0.00129 -> 1,006,745 DoFs

num_dof = mesh_wrapper(seed_size); %[output:615cd48a]
%%
%[text] ## {1}-ROM
%[text] ### Static dataset 
%[text] To create the {1}-ROM, the system (as defined in [.\\geometry\\mems\_arch\\mems\_arch.inp](file:.\\geometry\\mems_arch\\mems_arch.inp)), ROM limit and reduction basis needs to be specified.
%[text] Additionally the tangent stiffness at each loadcase is requested for later validation.
%--------- System Settings ---------%
system_name = "mems_arch";
energy_limit = 0.8; %(nJ)
reduction_basis = 1;
%-----------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.additional_data = "stiffness";
Static_Opts.num_validation_modes = 20;
Static_Opts.max_parallel_jobs =  1;
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"static_opts",Static_Opts); %[output:58b769a8] %[output:223efcd2] %[output:8d9590d2]
Static_Data = Static_Dataset(Model); %[output:620d6d12] %[output:0f8cbd07] %[output:2f6a94ac] %[output:496c3a13] %[output:3d8f3626] %[output:67f5ae44]
Static_Data.save_data; %[output:927ee36d]
%%
%[text] ### Periodic orbits
rom_name = "mems_arch_1";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:08734580]
Dyn_Data = Dyn_Data.remove_solution("all");
%[text] Store the maximum displacement at the centre of the upper arch for each orbit
Additional_Output.output = "physical displacement";
Additional_Output.type = "max";
dof.position = [0,36e-3,10e-3];
dof.direction = 2;
Additional_Output.dof = dof;
Dyn_Data = Dyn_Data.add_additional_output(Additional_Output);
%[text] The `Continuation_Opts` map to the corresponding continuation and collocation settings in COCO.
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 5e-1;
Continuation_Opts.max_inc = 5e-1;
Continuation_Opts.min_inc = 1e-2;

Continuation_Opts.forward_steps = 200;
Continuation_Opts.backward_steps = 0;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.initial_discretisation_num = 20;
%-----------------------------------------%

Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:9ddfbbdf]
compare_solutions("physical amplitude",Dyn_Data,1); %[output:2e4f0646] %[output:392a3476]
%%
%[text] #### Validation
set_visualisation_level(1)
compare_validation("mems_arch_1","validation error",1,1:6); %[output:8d91664a] %[output:4311b117]
%[text] The low amplitude orbits can be compared directly to explain the large predicted error at the linear solution
ax = compare_orbits(["v-d-1","v-v-1","v-d-2"],"mems_arch_1",{1,1}); %[output:5967d2cd] %[output:5576addd]
compare_orbits(["q-d-1","q-v-1","q-d-6"],"mems_arch_1",{1,1},"axes",ax); %[output:3728a851] %[output:5576addd]
%%
%[text] ## {1,6}-ROM
%[text] ### Static dataset
%[text] The original dataset can be re-used when creating the two-mode ROM
set_visualisation_level(3)

%--------- System Settings ---------%
added_mode = 6;
%-----------------------------------%
Static_Data = load_static_data("mems_arch_1") %[output:4c74fc91]

Static_Data = Static_Data.update_model(added_mode); %[output:8604350e] %[output:6d4a5236] %[output:2512e35b]
Static_Data = Static_Data.create_dataset; %[output:61aebd82]
Static_Data.save_data; %[output:8694dfc0]
%%
%[text] ### Periodic orbits
rom_name = "mems_arch_16";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:20ce5d03]
Dyn_Data = Dyn_Data.remove_solution("all");
%[text] Store the maximum displacement at the centre of the upper arch for each orbit
Additional_Output.output = "physical displacement";
Additional_Output.type = "max";
dof.position = [0,36e-3,10e-3];
dof.direction = 2;
Additional_Output.dof = dof;
Dyn_Data = Dyn_Data.add_additional_output(Additional_Output);
%[text] 
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 5e-1;
Continuation_Opts.max_inc = 5e-1;
Continuation_Opts.min_inc = 1e-2;
Continuation_Opts.forward_steps = 200;
Continuation_Opts.backward_steps = 0;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.initial_discretisation_num = 40;
%-----------------------------------------%
Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:82bbdf6b] %[output:19eb5a69] %[output:1c2e28cb] %[output:6db7eeda] %[output:47531d47]
%[text] Find the second branch predicted by the {1}:{1,6} validation
Dyn_Data_One_Mode = initalise_dynamic_data("mems_arch_1"); %[output:02b19fbb]
Sol = Dyn_Data_One_Mode.load_solution(1,"validation");
unstable_index = find(Sol.h_stability>1.01,3);
restart_index = unstable_index(2);
[orbit,validation_orbit] = Dyn_Data_One_Mode.get_orbit(1,restart_index,1);
[q,q_dot] = Dyn_Data_One_Mode.get_modal_validation_orbit(1,restart_index);
[min_ke,min_index] = min(sum(q_dot.^2,1));
test_ic = q(:,min_index);

potential_ic = initial_condition_sweep(Dyn_Data.Dynamic_Model,2*pi/orbit.T,test_ic); %[output:07668c55] %[output:7171f094] %[output:5eeb82e5]

Continuation_Opts.backward_steps = 5;
Dyn_Data = Dyn_Data.add_backbone(1,"ic",potential_ic,"opts",Continuation_Opts); %[output:6209ece8]
%[text] Plot them together
compare_solutions("physical amplitude","mems_arch_16","all"); %[output:5fcfcdf8] %[output:9e981d6f] %[output:2512f471]
%%
%[text] #### Validation
set_visualisation_level(1)
compare_validation("mems_arch_16","validation error",[1,2],"all"); %[output:16a2f477] %[output:5c21dd4d] %[output:9983e639]
compare_validation("mems_arch_16","validation error",[1,2],[5,11,13]); %[output:1b500df2] %[output:2b9163aa] %[output:0c7723de]

